  public static void BuildAndroidRelease() {
    Setup();
    foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/Resources/Art" })) {
      var ti = (TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid));
      ti.mipmapEnabled = false; ti.maxTextureSize = 1280; ti.crunchedCompression = true; ti.compressionQuality = 50;
      var a = ti.GetPlatformTextureSettings("Android"); a.overridden = true; a.maxTextureSize = 1280; a.format = TextureImporterFormat.ASTC_6x6; ti.SetPlatformTextureSettings(a);
      ti.SaveAndReimport(); }
    PlayerSettings.SetManagedStrippingLevel(UnityEditor.Build.NamedBuildTarget.Android, ManagedStrippingLevel.High);
    PlayerSettings.stripEngineCode = true;
    PlayerSettings.SetIl2CppCompilerConfiguration(UnityEditor.Build.NamedBuildTarget.Android, Il2CppCompilerConfiguration.Master);
    PlayerSettings.SetIl2CppCodeGeneration(UnityEditor.Build.NamedBuildTarget.Android, UnityEditor.Build.Il2CppCodeGeneration.OptimizeSize);
    EditorUserBuildSettings.androidBuildSubtarget = MobileTextureSubtarget.ASTC;
    EditorUserBuildSettings.development = false;
    EditorUserBuildSettings.buildAppBundle = false; PlayerSettings.Android.useCustomKeystore = false;
    var r = BuildPipeline.BuildPlayer(new BuildPlayerOptions { scenes = new[] { Scene }, locationPathName = "/workspace/Galeborne_v0.4.apk", target = BuildTarget.Android, options = BuildOptions.CompressWithLz4HC });
    Debug.Log($"GB ANDROID REL {r.summary.result} errors={r.summary.totalErrors}"); if (r.summary.result != BuildResult.Succeeded) EditorApplication.Exit(1);
  }
