  /* k4 texq: Android texture rules. Size = source pixels rounded up to Unity's next allowed max size (32..2048), no crunch, quality 100. */
  static bool K4Is4x4(string p) { string f = Path.GetFileName(p).ToLowerInvariant(); string l = p.ToLowerInvariant();
    return l.Contains("/keepers/") || l.Contains("/portraits/") || l.Contains("/goodsicons/") || f.StartsWith("ui_") || f.Contains("portrait") || f.Contains("captain") || f.Contains("character") || f.Contains("icon") || f.StartsWith("coin_"); }
  static int K4Size(TextureImporter ti) { int w, h; ti.GetSourceTextureWidthAndHeight(out w, out h); int m = Math.Max(w, h), s = 32; while (s < m && s < 2048) s *= 2; return s; }
  static void K4TexQuality() {
    var folders = new[] { "Assets/Resources/Art", "Assets/Resources/Keepers", "Assets/Resources/GoodsIcons", "Assets/Resources/Ship" }; /* LandmarksK4 deliberately excluded: Chief Art Designer owns those import settings */
    foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", folders)) { var path = AssetDatabase.GUIDToAssetPath(guid); var ti = AssetImporter.GetAtPath(path) as TextureImporter; if (ti == null) continue;
      int sz = K4Size(ti); var fmt = K4Is4x4(path) ? TextureImporterFormat.ASTC_4x4 : TextureImporterFormat.ASTC_6x6;
      ti.maxTextureSize = sz; ti.crunchedCompression = false; ti.compressionQuality = 100;
      var a = ti.GetPlatformTextureSettings("Android"); a.overridden = true; a.maxTextureSize = sz; a.crunchedCompression = false; a.compressionQuality = 100; a.format = fmt; ti.SetPlatformTextureSettings(a); ti.SaveAndReimport();
      Debug.Log($"GB K4TEX {path} max={sz} fmt={fmt} crunch=false"); }
    Debug.Log("GB K4 texture quality applied"); }
  public static void BuildAndroidReleaseTo(string path) {
    Setup();
    /* k4 texq: old crunch/1280/ASTC 10x10 and 512-normal / 256-portrait caps removed; K4TexQuality() runs after HQ/MQ below */
    if (path.Contains("_hq")) HQPass();
    if (path.Contains("_mq")) MQPass();
    K4TexQuality(); /* k4 (Jeff): no crunch, source size up to 2048, ASTC 4x4 UI/characters, 6x6 rest; wins over MQPass */
    PlayerSettings.SetManagedStrippingLevel(UnityEditor.Build.NamedBuildTarget.Android, ManagedStrippingLevel.High); PlayerSettings.stripEngineCode = true;
